vulnerable_code:
app.get('/api/profile/details/:accountId', async (req, res) => {
  const details = await Profile.findOne({ account: req.params.accountId });
  res.json(details);
});

corrected_code:
app.get('/api/profile/details/:accountId', async (req, res) => {
  if (req.params.accountId !== req.user.accountId) return res.status(403).send('Forbidden');
  const details = await Profile.findOne({ account: req.params.accountId });
  res.json(details);
});
